    key string
    val []byte
}

type LRU struct {
    mu    sync.Mutex
    cap   int
    ll    *list.List               // old: front = eng yangi
    items map[string]*list.Element
}

func (c *LRU) Get(k string) ([]byte, bool) {
    c.mu.Lock()
    defer c.mu.Unlock()
    if e, ok := c.items[k]; ok {
        c.ll.MoveToFront(e)
        return e.Value.(*entry).val, true
    }
    return nil, false
}

func (c *LRU) Put(k string, v []byte) {
    c.mu.Lock()
    defer c.mu.Unlock()
    if e, ok := c.items[k]; ok {
        e.Value.(*entry).val = v
        c.ll.MoveToFront(e)
        return
    }
    c.items[k] = c.ll.PushFront(&entry{k, v})
    if c.ll.Len() > c.cap {
        old := c.ll.Back()
        c.ll.Remove(old)
        delete(c.items, old.Value.(*entry).key)
    }
}

